-- Verse Snap: Reflection Journal (notebooks and reflections) for signed-in accounts.
--
-- NOT YET APPROVED FOR THE LIVE PROJECT. Apply only after explicit approval, and only to the
-- independent project (ref shoztcflucpnfenohgcr). Rollback: supabase/rollbacks/ (same name).
--
-- notebooks
--   One "General Reflections" default per person (partial unique index), which can't be deleted.
--   Names are unique per person, ignoring case. Ids may be generated by the app, so a guest
--   notebook keeps its id when it is added to an account (retry-safe import).
-- reflections
--   One reflection per person, translation and verse (the editor reopens it). Each belongs to one
--   of the SAME person's notebooks: the foreign key is (notebook_id, user_id), so a reflection can
--   never point at someone else's notebook. A reflection needs a title or some text.
-- Safe delete
--   Deleting a notebook moves its reflections to the person's default notebook (trigger), so no
--   reflection is lost. The foreign key is NO ACTION, so if anything ever tried to remove a
--   notebook that still has reflections, the delete fails instead of deleting notes. Deleting an
--   account deletes its notebooks and reflections (cascade).
-- Security
--   RLS: each person reads and writes only their own rows (auth.uid() = user_id).
--   Grants are explicit: signed-out (anon) gets nothing. Signed-in gets SELECT, INSERT, DELETE and
--   UPDATE of the editable columns only (never id, owner, verse, or a notebook's default flag).
-- Nothing existing is changed.

begin;

create table public.notebooks (
  id uuid not null default gen_random_uuid() primary key,
  user_id uuid not null references auth.users (id) on delete cascade,
  name text not null check (name = btrim(name) and char_length(name) between 1 and 60),
  is_default boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  -- Target of the reflections' (notebook_id, user_id) foreign key.
  constraint notebooks_id_user_key unique (id, user_id)
);

create unique index notebooks_user_name_key on public.notebooks (user_id, lower(name));
create unique index notebooks_user_default_key on public.notebooks (user_id) where is_default;

create table public.reflections (
  id uuid not null default gen_random_uuid() primary key,
  user_id uuid not null references auth.users (id) on delete cascade,
  notebook_id uuid not null,
  translation text not null,
  book_id text not null,
  chapter integer not null check (chapter > 0),
  verse integer not null check (verse > 0),
  title text not null default '' check (char_length(title) <= 120),
  body text not null default '' check (char_length(body) <= 20000),
  tags text[] not null default '{}' check (cardinality(tags) <= 20),
  posture text check (char_length(posture) between 1 and 40),
  is_private boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint reflections_not_empty check (btrim(title) <> '' or btrim(body) <> ''),
  constraint reflections_verse_key unique (user_id, translation, book_id, chapter, verse),
  constraint reflections_notebook_fkey foreign key (notebook_id, user_id)
    references public.notebooks (id, user_id)
);

-- Journal list (newest first) and the notebook move on delete.
create index reflections_user_updated_idx on public.reflections (user_id, updated_at desc);
create index reflections_notebook_idx on public.reflections (notebook_id);

comment on table public.notebooks is
  'Reflection notebooks: one undeletable default per user; names unique per user (any case).';
comment on table public.reflections is
  'Reflections: one per user, translation and verse, always in one of the same user''s notebooks.';

-- Deleting a notebook moves its reflections to the owner's default notebook. SECURITY DEFINER so
-- it can tell an account deletion (auth.users row gone: nothing to keep) from a normal delete;
-- the delete itself has already passed RLS, and the update is limited to that owner's rows.
create function public.notebooks_move_reflections()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  fallback uuid;
begin
  if not exists (select 1 from auth.users where id = old.user_id) then
    return old;
  end if;
  if old.is_default then
    raise exception 'The default notebook can''t be deleted' using errcode = 'P0001';
  end if;
  select id into fallback from public.notebooks where user_id = old.user_id and is_default;
  if fallback is null then
    raise exception 'No default notebook to move the reflections to' using errcode = 'P0001';
  end if;
  update public.reflections
     set notebook_id = fallback, updated_at = now()
   where notebook_id = old.id and user_id = old.user_id;
  return old;
end;
$$;

revoke execute on function public.notebooks_move_reflections() from public, anon, authenticated;

create trigger notebooks_move_reflections
  before delete on public.notebooks
  for each row execute function public.notebooks_move_reflections();

alter table public.notebooks enable row level security;
alter table public.reflections enable row level security;

create policy "Users can manage their own notebooks" on public.notebooks
  for all to authenticated
  using ((select auth.uid()) = user_id)
  with check ((select auth.uid()) = user_id);

create policy "Users can manage their own reflections" on public.reflections
  for all to authenticated
  using ((select auth.uid()) = user_id)
  with check ((select auth.uid()) = user_id);

revoke all on public.notebooks, public.reflections from public, anon, authenticated;
grant select, insert, delete on public.notebooks, public.reflections to authenticated;
grant update (name, updated_at) on public.notebooks to authenticated;
grant update (notebook_id, title, body, tags, posture, is_private, updated_at)
  on public.reflections to authenticated;
grant all on public.notebooks, public.reflections to service_role;

commit;
